-}
+const TTL_MS = 60_000;
+const cache = new Map();
+
+function lookupCached(sku) {
+  const hit = cache.get(sku);
+  if (hit && hit.expires > Date.now()) return hit.promise;
+
+  const promise = pricing.lookup(sku);
+  cache.set(sku, { promise, expires: Date.now() + TTL_MS });
+  return promise;
+}
+
+export async function getPrices(skus) {
+  const result = {};
+  await Promise.all(
+    skus.map(async (sku) => {
+      result[sku] = await lookupCached(sku);
+    }),
+  );
+  return Object.values(result);
+}
